/**
 * Generate the TypeScript main.ts entrypoint for Hono on Cloud Run.
 */
function tsMain(): string {
  return [
    GENERATED_HEADER_TS,
    `import { serve } from '@hono/node-server';`,
    `import { app } from './routes.js';`,
    '',
    'const PORT = parseInt(process.env.PORT ?? \'8080\', 10);',
    '',
    'serve({ fetch: app.fetch, port: PORT }, (info) => {',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'HTTP server started\',',
    '      port: info.port,',
    '      pid: process.pid,',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '});',
    '',
    'process.on(\'SIGTERM\', () => {',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'Received SIGTERM — shutting down gracefully\',',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '  process.exit(0);',
    '});',
    '',
  ].join('\n');
}

/**
 * Generate TypeScript routes.ts with one POST route per command and one GET
 * route per query, across all bounded contexts.
 */
function tsRoutes(
  contexts: readonly { name: string; commands: readonly { name: string; description?: string; input?: readonly string[]; preconditions?: readonly string[]; postconditions?: readonly string[] }[]; queries: readonly { name: string; description?: string; parameters?: readonly string[]; returns?: string }[]; entities?: readonly { name: string; description: string }[]; valueObjects?: readonly { name: string; description: string }[] }[],
): { content: string; routeCount: number } {
  const lines: string[] = [
    GENERATED_HEADER_TS,
    `import { Hono } from 'hono';`,
    `import * as crypto from 'node:crypto';`,
    `import { correlationMiddleware, iamMiddleware, loggingMiddleware } from './middleware.js';`,
    `import { healthRouter } from './health.js';`,
    '',
    'const app = new Hono();',
    '',
    '// Global middleware',
    'app.use(\'*\', correlationMiddleware);',
    'app.use(\'*\', iamMiddleware);',
    'app.use(\'*\', loggingMiddleware);',
    '',
    '// Health endpoints',
    `app.route('/health', healthRouter);`,
    '',
  ];

  let routeCount = 0;

  for (const ctx of contexts) {
    const ctxSlug = slugify(ctx.name.replace(/Context$/i, ''));
    lines.push(`// Bounded context: ${ctx.name}`);

    for (const cmd of ctx.commands) {
      const cmdSlug = slugify(cmd.name);
      lines.push(`app.post('/api/${ctxSlug}/${cmdSlug}', async (c) => {`);
      lines.push(`  const correlationId = c.get('correlationId') as string;`);
      lines.push(`  try {`);
      lines.push(`    const body = await c.req.json();`);
      // Domain-model-driven mock handler
      const cmdInfo: CommandMockInfo | undefined = cmd.input ? {
        name: cmd.name,
        description: cmd.description ?? '',
        inputFields: cmd.input ?? [],
        preconditions: cmd.preconditions ?? [],
        postconditions: cmd.postconditions ?? [],
        boundedContext: ctx.name,
      } : undefined;
      const cmdMockLines = buildMockCommandBody(ctxSlug, cmdSlug, cmdInfo, ctx.entities, ctx.valueObjects);
      lines.push(...cmdMockLines);
      lines.push(`  } catch (err) {`);
      lines.push(`    const message = err instanceof Error ? err.message : 'Unknown error';`);
      lines.push(`    return c.json({ error: { code: 'COMMAND_ERROR', message }, correlationId }, 500);`);
      lines.push(`  }`);
      lines.push(`});`);
      lines.push('');
      routeCount++;
    }

    for (const query of ctx.queries) {
      const querySlug = slugify(query.name);
      lines.push(`app.get('/api/${ctxSlug}/${querySlug}', async (c) => {`);
      lines.push(`  const correlationId = c.get('correlationId') as string;`);
      lines.push(`  try {`);
      lines.push(`    const params = c.req.query();`);
      // Domain-model-driven mock handler
      const queryInfo: QueryMockInfo | undefined = query.parameters ? {
        name: query.name,
        description: query.description ?? '',
        parameters: query.parameters ?? [],
        returns: query.returns ?? 'unknown',
        boundedContext: ctx.name,
      } : undefined;
      const queryMockLines = buildMockQueryBody(ctxSlug, querySlug, queryInfo, ctx.entities, ctx.valueObjects);
      lines.push(...queryMockLines);
      lines.push(`  } catch (err) {`);
      lines.push(`    const message = err instanceof Error ? err.message : 'Unknown error';`);
      lines.push(`    return c.json({ error: { code: 'QUERY_ERROR', message }, correlationId }, 500);`);
      lines.push(`  }`);
      lines.push(`});`);
      lines.push('');
      routeCount++;
    }
  }

  lines.push('export { app };');
  lines.push('');

  return { content: lines.join('\n'), routeCount };
}

/**
 * Generate TypeScript middleware.ts with IAM token validation,
 * correlation ID injection, and structured request/response logging.
 */
function tsMiddleware(): string {
  return [
    GENERATED_HEADER_TS,
    `import type { MiddlewareHandler } from 'hono';`,
    `import { createMiddleware } from 'hono/factory';`,
    `import * as crypto from 'node:crypto';`,
    '',
    '// ---------------------------------------------------------------------------',
    '// Correlation ID middleware',
    '// ---------------------------------------------------------------------------',
    '',
    '/**',
    ' * Injects or propagates X-Correlation-ID for request tracing.',
    ' */',
    'export const correlationMiddleware: MiddlewareHandler = createMiddleware(async (c, next) => {',
    '  const correlationId = c.req.header(\'X-Correlation-ID\') ?? crypto.randomUUID();',
    '  c.set(\'correlationId\', correlationId);',
    '  c.header(\'X-Correlation-ID\', correlationId);',
    '  await next();',
    '});',
    '',
    '// ---------------------------------------------------------------------------',
    '// IAM token validation middleware (GCP identity token via JWKS)',
    '// ---------------------------------------------------------------------------',
    '',
    '/**',
    ' * Validates GCP service account identity tokens on every inbound request.',
    ' * Skips validation for health check endpoints.',
    ' */',
    'export const iamMiddleware: MiddlewareHandler = createMiddleware(async (c, next) => {',
    '  // Skip IAM check for health/readiness probes',
    '  const path = new URL(c.req.url).pathname;',
    '  if (path === \'/health/healthz\' || path === \'/health/readyz\') {',
    '    await next();',
    '    return;',
    '  }',
    '',
    '  const authHeader = c.req.header(\'Authorization\');',
    '  if (!authHeader?.startsWith(\'Bearer \')) {',
    '    return c.json({ error: { code: \'UNAUTHORIZED\', message: \'Missing Bearer token\' } }, 401);',
    '  }',
    '',
    '  const token = authHeader.slice(7);',
    '  // TODO: verify GCP identity token via JWKS endpoint:',
    '  // https://www.googleapis.com/oauth2/v3/certs',
    '  // Validate iss, aud, exp claims.',
    '  if (!token) {',
    '    return c.json({ error: { code: \'UNAUTHORIZED\', message: \'Invalid token\' } }, 401);',
    '  }',
    '',
    '  await next();',
    '});',
    '',
    '// ---------------------------------------------------------------------------',
    '// Structured JSON request/response logging middleware',
    '// ---------------------------------------------------------------------------',
    '',
    '/**',
    ' * Emits structured JSON log lines for each request and response.',
    ' */',
    'export const loggingMiddleware: MiddlewareHandler = createMiddleware(async (c, next) => {',
    '  const startTime = Date.now();',
    '  const correlationId = c.get(\'correlationId\') as string | undefined;',
    '',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'request received\',',
    '      httpRequest: {',
    '        method: c.req.method,',
    '        url: c.req.url,',
    '        userAgent: c.req.header(\'user-agent\'),',
    '      },',
    '      correlationId,',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '',
    '  await next();',
    '',
    '  const durationMs = Date.now() - startTime;',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'request completed\',',
    '      httpRequest: {',
    '        method: c.req.method,',
    '        url: c.req.url,',
    '        status: c.res.status,',
    '        latency: `${durationMs}ms`,',
    '      },',
    '      correlationId,',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '});',
    '',
  ].join('\n');
}

/**
 * Generate TypeScript health.ts with /healthz and /readyz endpoints.
 */
function tsHealth(): string {
  return [
    GENERATED_HEADER_TS,
    `import { Hono } from 'hono';`,
    '',
    'export const healthRouter = new Hono();',
    '',
    '/**',
    ' * GET /healthz',
    ' * Liveness probe — returns 200 when the process is running.',
    ' */',
    'healthRouter.get(\'/healthz\', (c) => {',
    '  return c.json({ status: \'ok\' }, 200);',
    '});',
    '',
    '/**',
    ' * GET /readyz',
    ' * Readiness probe — returns 200 when the service is ready to receive traffic.',
    ' */',
    'healthRouter.get(\'/readyz\', (c) => {',
    '  return c.json({ status: \'ready\' }, 200);',
    '});',
    '',
  ].join('\n');
}

