/**
 * Generate Rust main.rs entrypoint for Axum on Cloud Run.
 */
function rustMain(): string {
  return [
    GENERATED_HEADER_RS,
    'mod health;',
    'mod middleware;',
    'mod routes;',
    '',
    'use axum::Router;',
    'use std::net::SocketAddr;',
    '',
    '#[tokio::main]',
    'async fn main() {',
    '    let port: u16 = std::env::var("PORT")',
    '        .unwrap_or_else(|_| "8080".to_string())',
    '        .parse()',
    '        .expect("PORT must be a valid port number");',
    '',
    '    let app = routes::create_router();',
    '',
    '    let addr = SocketAddr::from(([0, 0, 0, 0], port));',
    '    println!("{}", serde_json::json!({',
    '        "severity": "INFO",',
    '        "message": "HTTP server started",',
    '        "port": port,',
    '        "timestamp": chrono::Utc::now().to_rfc3339()',
    '    }));',
    '',
    '    axum::Server::bind(&addr)',
    '        .serve(app.into_make_service())',
    '        .await',
    '        .unwrap();',
    '}',
    '',
  ].join('\n');
}

/**
 * Generate Rust routes.rs with axum Router and route handlers.
 */
function rustRoutes(
  contexts: readonly { name: string; commands: readonly { name: string }[]; queries: readonly { name: string }[]; entities?: readonly { name: string; description: string }[]; valueObjects?: readonly { name: string; description: string }[] }[],
): { content: string; routeCount: number } {
  const lines: string[] = [
    GENERATED_HEADER_RS,
    'use axum::{',
    '    extract::Query,',
    '    http::StatusCode,',
    '    response::Json,',
    '    routing::{get, post},',
    '    Router,',
    '};',
    'use serde_json::{json, Value};',
    'use std::collections::HashMap;',
    'use tokio;',
    '',
    'pub fn create_router() -> Router {',
    '    Router::new()',
    '        .route("/health/healthz", get(crate::health::healthz))',
    '        .route("/health/readyz", get(crate::health::readyz))',
  ];

  let routeCount = 0;

  for (const ctx of contexts) {
    const ctxSlug = slugify(ctx.name.replace(/Context$/i, ''));

    for (const cmd of ctx.commands) {
      const cmdSlug = slugify(cmd.name);
      const fnName = snakeCase(cmd.name);
      lines.push(`        .route("/api/${ctxSlug}/${cmdSlug}", post(handle_${fnName}))`);
      routeCount++;
    }

    for (const query of ctx.queries) {
      const querySlug = slugify(query.name);
      const fnName = snakeCase(query.name);
      lines.push(`        .route("/api/${ctxSlug}/${querySlug}", get(handle_${fnName}))`);
      routeCount++;
    }
  }

  lines.push('}');
  lines.push('');

  for (const ctx of contexts) {
    const ctxSlug = slugify(ctx.name.replace(/Context$/i, ''));
    lines.push(`// Bounded context: ${ctx.name}`);

    for (const cmd of ctx.commands) {
      const fnName = snakeCase(cmd.name);
      const cmdSlug = slugify(cmd.name);
      lines.push(`async fn handle_${fnName}(`);
      lines.push(`    Json(body): Json<Value>,`);
      lines.push(`) -> Result<Json<Value>, StatusCode> {`);
      lines.push(`    let start = std::time::Instant::now();`);
      lines.push(`    // Simulated processing delay`);
      lines.push(`    tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;`);
      lines.push(buildRustMockCommandJson(ctxSlug, cmdSlug));
      lines.push(`}`);
      lines.push('');
    }

    for (const query of ctx.queries) {
      const fnName = snakeCase(query.name);
      const querySlug = slugify(query.name);
      lines.push(`async fn handle_${fnName}(`);
      lines.push(`    Query(params): Query<HashMap<String, String>>,`);
      lines.push(`) -> Result<Json<Value>, StatusCode> {`);
      lines.push(buildRustMockQueryJson(ctxSlug, querySlug));
      lines.push(`}`);
      lines.push('');
    }
  }

  return { content: lines.join('\n'), routeCount };
}

/**
 * Generate Rust middleware.rs with Tower middleware layers.
 */
function rustMiddleware(): string {
  return [
    GENERATED_HEADER_RS,
    'use axum::{',
    '    body::Body,',
    '    http::{Request, Response},',
    '    middleware::Next,',
    '    response::IntoResponse,',
    '};',
    'use uuid::Uuid;',
    '',
    '/// Inject or propagate X-Correlation-ID for request tracing.',
    'pub async fn correlation_middleware(',
    '    mut req: Request<Body>,',
    '    next: Next<Body>,',
    ') -> impl IntoResponse {',
    '    let correlation_id = req',
    '        .headers()',
    '        .get("x-correlation-id")',
    '        .and_then(|v| v.to_str().ok())',
    '        .map(|s| s.to_string())',
    '        .unwrap_or_else(|| Uuid::new_v4().to_string());',
    '',
    '    req.extensions_mut().insert(correlation_id.clone());',
    '',
    '    let mut response = next.run(req).await;',
    '    response.headers_mut().insert(',
    '        "x-correlation-id",',
    '        correlation_id.parse().unwrap(),',
    '    );',
    '    response',
    '}',
    '',
    '/// Validate GCP service account identity tokens (JWKS verification).',
    'pub async fn iam_middleware(',
    '    req: Request<Body>,',
    '    next: Next<Body>,',
    ') -> impl IntoResponse {',
    '    let path = req.uri().path().to_string();',
    '    if path == "/health/healthz" || path == "/health/readyz" {',
    '        return next.run(req).await.into_response();',
    '    }',
    '',
    '    let auth_header = req',
    '        .headers()',
    '        .get("authorization")',
    '        .and_then(|v| v.to_str().ok())',
    '        .map(|s| s.to_string());',
    '',
    '    match auth_header {',
    '        Some(header) if header.starts_with("Bearer ") => {',
    '            // TODO: verify GCP identity token via JWKS endpoint',
    '            // https://www.googleapis.com/oauth2/v3/certs',
    '            next.run(req).await.into_response()',
    '        }',
    '        _ => axum::http::Response::builder()',
    '            .status(401)',
    '            .body(axum::body::Body::from(r#"{"error":{"code":"UNAUTHORIZED"}}"#))',
    '            .unwrap()',
    '            .into_response(),',
    '    }',
    '}',
    '',
    '/// Emit structured JSON log lines for each request and response.',
    'pub async fn logging_middleware(',
    '    req: Request<Body>,',
    '    next: Next<Body>,',
    ') -> impl IntoResponse {',
    '    let method = req.method().clone();',
    '    let uri = req.uri().clone();',
    '    let start = std::time::Instant::now();',
    '',
    '    println!("{}", serde_json::json!({',
    '        "severity": "INFO",',
    '        "message": "request received",',
    '        "httpRequest": { "method": method.as_str(), "url": uri.to_string() },',
    '        "timestamp": chrono::Utc::now().to_rfc3339()',
    '    }));',
    '',
    '    let response = next.run(req).await;',
    '    let duration_ms = start.elapsed().as_millis();',
    '',
    '    println!("{}", serde_json::json!({',
    '        "severity": "INFO",',
    '        "message": "request completed",',
    '        "httpRequest": {',
    '            "method": method.as_str(),',
    '            "url": uri.to_string(),',
    '            "status": response.status().as_u16(),',
    '            "latency": format!("{}ms", duration_ms)',
    '        },',
    '        "timestamp": chrono::Utc::now().to_rfc3339()',
    '    }));',
    '',
    '    response',
    '}',
    '',
  ].join('\n');
}

/**
 * Generate Rust health.rs with healthz and readyz handlers.
 */
function rustHealth(): string {
  return [
    GENERATED_HEADER_RS,
    'use axum::{http::StatusCode, response::Json};',
    'use serde_json::{json, Value};',
    '',
    '/// GET /health/healthz — liveness probe.',
    'pub async fn healthz() -> (StatusCode, Json<Value>) {',
    '    (StatusCode::OK, Json(json!({ "status": "ok" })))',
    '}',
    '',
    '/// GET /health/readyz — readiness probe.',
    'pub async fn readyz() -> (StatusCode, Json<Value>) {',
    '    (StatusCode::OK, Json(json!({ "status": "ready" })))',
    '}',
    '',
  ].join('\n');
}

// ============================================================================
// File Writing
// ============================================================================

/**
 * Write a server file to disk, creating parent directories as needed.
 */
function writeServerFile(absPath: string, content: string): void {
  const dir = absPath.substring(0, absPath.lastIndexOf('/'));
  mkdirSync(dir, { recursive: true, mode: DIR_MODE });
  try {
    writeFileSync(absPath, content, { encoding: 'utf-8', mode: FILE_MODE });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(`ECLI-P4-051: Failed to write server file ${absPath}: ${message}`);
  }
}

// ============================================================================
// Public: Pipeline Entry Point
// ============================================================================

/**
 * Stage 5 entry point: generate Cloud Run-compatible HTTP server code
 * for the resolved implementation language.
 *
 * Reads ERPResolution from context.stageOutputs.get('erp-target-resolution'),
 * reads bounded contexts from Phase 2 domain model, and writes server files
 * to phase4/project/src/server/.
 *
 * @param context - The Phase 4 pipeline context
 * @returns Stage output describing success or failure
 */
export function generateHttpServer(context: Phase4Context): Phase4StageOutput {
  const startTime = Date.now();
  const rootSpan = createSpan('http-server-generation', 'generate-http-server', {
    phase4Dir: context.phase4Dir,
    traceId: context.traceId,
  });

  try {
    // Verify ERP target resolution completed
    const erpStage = context.stageOutputs.get('erp-target-resolution');
    if (!erpStage || erpStage.status !== 'completed') {
      throw new Error(
        'ECLI-P4-050: ERP target resolution not available on context. ' +
        'Ensure the erp-target-resolution stage completed successfully before running http-server-generation.',
      );
    }
    const erpResolution = erpStage.data as ERPResolution;
    void erpResolution;

    // Resolve implementation language and bounded contexts
    const language = context.phase3Artifacts.implementationLanguage;
    const domainModel = context.phase3Artifacts.phase2Artifacts.domainModel;

    // Flatten commands/queries/entities/VOs from aggregates to context level for route generation.
    // The DDD domain model stores commands/queries inside aggregates, but the route
    // generator needs them at the context level along with entity/VO metadata for mock generation.
    const contexts = (domainModel.contexts as unknown as readonly Record<string, unknown>[]).map((ctx) => {
      const aggregates = (ctx['aggregates'] as readonly Record<string, unknown>[] | undefined) ?? [];
      const commands: { name: string; description?: string; input?: readonly string[]; preconditions?: readonly string[]; postconditions?: readonly string[] }[] = [];
      const queries: { name: string; description?: string; parameters?: readonly string[]; returns?: string }[] = [];
      const entities: { name: string; description: string }[] = [];
      const valueObjects: { name: string; description: string }[] = [];

      for (const agg of aggregates) {
        const aggCommands = (agg['commands'] as readonly Record<string, unknown>[] | undefined) ?? [];
        const aggQueries = (agg['queries'] as readonly Record<string, unknown>[] | undefined) ?? [];
        const aggEntities = (agg['entities'] as readonly Record<string, unknown>[] | undefined) ?? [];
        const aggVOs = (agg['valueObjects'] as readonly Record<string, unknown>[] | undefined) ?? [];

        // Collect commands with full metadata
        for (const cmd of aggCommands) {
          commands.push({
            name: cmd['name'] as string,
            description: (cmd['description'] as string | undefined) ?? '',
            input: (cmd['input'] as readonly string[] | undefined) ?? [],
            preconditions: (cmd['preconditions'] as readonly string[] | undefined) ?? [],
            postconditions: (cmd['postconditions'] as readonly string[] | undefined) ?? [],
          });
        }
        // Collect queries with full metadata
        for (const q of aggQueries) {
          queries.push({
            name: q['name'] as string,
            description: (q['description'] as string | undefined) ?? '',
            parameters: (q['parameters'] as readonly string[] | undefined) ?? [],
            returns: (q['returns'] as string | undefined) ?? 'unknown',
          });
        }
        // Collect entities and value objects
        for (const ent of aggEntities) {
          entities.push({ name: ent['name'] as string, description: (ent['description'] as string | undefined) ?? '' });
        }
        for (const vo of aggVOs) {
          valueObjects.push({ name: vo['name'] as string, description: (vo['description'] as string | undefined) ?? '' });
        }
      }

      // Also include any commands/queries already present at context level
      const ctxCommands = (ctx['commands'] as readonly Record<string, unknown>[] | undefined) ?? [];
      const ctxQueries = (ctx['queries'] as readonly Record<string, unknown>[] | undefined) ?? [];
      for (const cmd of ctxCommands) {
        commands.push({
          name: (cmd as Record<string, unknown>)['name'] as string,
          description: ((cmd as Record<string, unknown>)['description'] as string | undefined) ?? '',
          input: ((cmd as Record<string, unknown>)['input'] as readonly string[] | undefined) ?? [],
          preconditions: ((cmd as Record<string, unknown>)['preconditions'] as readonly string[] | undefined) ?? [],
          postconditions: ((cmd as Record<string, unknown>)['postconditions'] as readonly string[] | undefined) ?? [],
        });
      }
      for (const q of ctxQueries) {
        queries.push({
          name: (q as Record<string, unknown>)['name'] as string,
          description: ((q as Record<string, unknown>)['description'] as string | undefined) ?? '',
          parameters: ((q as Record<string, unknown>)['parameters'] as readonly string[] | undefined) ?? [],
          returns: ((q as Record<string, unknown>)['returns'] as string | undefined) ?? 'unknown',
        });
      }

      return { name: ctx['name'] as string, commands, queries, entities, valueObjects };
    });

    const isTs = language === 'typescript';
    const framework: 'hono' | 'axum' = isTs ? 'hono' : 'axum';

    // Output directory: phase4/project/src/server/
    const serverDir = join(context.phase4Dir, 'project', 'src', 'server');
    mkdirSync(serverDir, { recursive: true, mode: DIR_MODE });

    const serverFiles: ServerFile[] = [];
    const writtenPaths: string[] = [];

    const genSpan = createSpan(
      'http-server-generation',
      'generate-files',
      { language, framework, contextCount: contexts.length },
      rootSpan.spanId,
    );

    if (isTs) {
      // main.ts
      const mainContent = tsMain();
      const mainPath = join(serverDir, 'main.ts');
      writeServerFile(mainPath, mainContent);
      serverFiles.push({ relativePath: 'project/src/server/main.ts', content: mainContent, kind: 'server' });
      writtenPaths.push(mainPath);

      // routes.ts
      const { content: routesContent, routeCount } = tsRoutes(contexts);
      const routesPath = join(serverDir, 'routes.ts');
      writeServerFile(routesPath, routesContent);
      serverFiles.push({ relativePath: 'project/src/server/routes.ts', content: routesContent, kind: 'server' });
      writtenPaths.push(routesPath);

      // middleware.ts
      const middlewareContent = tsMiddleware();
      const middlewarePath = join(serverDir, 'middleware.ts');
      writeServerFile(middlewarePath, middlewareContent);
      serverFiles.push({ relativePath: 'project/src/server/middleware.ts', content: middlewareContent, kind: 'server' });
      writtenPaths.push(middlewarePath);

      // health.ts
      const healthContent = tsHealth();
      const healthPath = join(serverDir, 'health.ts');
      writeServerFile(healthPath, healthContent);
      serverFiles.push({ relativePath: 'project/src/server/health.ts', content: healthContent, kind: 'server' });
      writtenPaths.push(healthPath);

      const finalGenSpan = endSpan(genSpan, 'ok', { filesGenerated: 4, routeCount });
      emitSpan(finalGenSpan);

      const finalRootSpan = endSpan(rootSpan, 'ok', { framework, filesGenerated: 4, routeCount });
      emitSpan(finalRootSpan);

      const timing = Date.now() - startTime;
      const output: Phase4StageOutput = {
        stage: 'http-server-generation',
        status: 'completed',
        data: {
          framework,
          files: serverFiles,
          routeCount,
        } satisfies HttpServerOutput,
        artifacts: writtenPaths,
        timing,
        summary:
          `Generated ${framework} HTTP server (${language}): ` +
          `${routeCount} routes across ${contexts.length} bounded contexts ` +
          `(${writtenPaths.length} files in ${timing}ms)`,
      };

      context.stageOutputs.set('http-server-generation', output);
      return output;
    } else {
      // Rust: main.rs, routes.rs, middleware.rs, health.rs
      const mainContent = rustMain();
      const mainPath = join(serverDir, 'main.rs');
      writeServerFile(mainPath, mainContent);
      serverFiles.push({ relativePath: 'project/src/server/main.rs', content: mainContent, kind: 'server' });
      writtenPaths.push(mainPath);

      const { content: routesContent, routeCount } = rustRoutes(contexts);
      const routesPath = join(serverDir, 'routes.rs');
      writeServerFile(routesPath, routesContent);
      serverFiles.push({ relativePath: 'project/src/server/routes.rs', content: routesContent, kind: 'server' });
      writtenPaths.push(routesPath);

      const middlewareContent = rustMiddleware();
      const middlewarePath = join(serverDir, 'middleware.rs');
      writeServerFile(middlewarePath, middlewareContent);
      serverFiles.push({ relativePath: 'project/src/server/middleware.rs', content: middlewareContent, kind: 'server' });
      writtenPaths.push(middlewarePath);

      const healthContent = rustHealth();
      const healthPath = join(serverDir, 'health.rs');
      writeServerFile(healthPath, healthContent);
      serverFiles.push({ relativePath: 'project/src/server/health.rs', content: healthContent, kind: 'server' });
      writtenPaths.push(healthPath);

      const finalGenSpan = endSpan(genSpan, 'ok', { filesGenerated: 4, routeCount });
      emitSpan(finalGenSpan);

      const finalRootSpan = endSpan(rootSpan, 'ok', { framework, filesGenerated: 4, routeCount });
      emitSpan(finalRootSpan);

      const timing = Date.now() - startTime;
      const output: Phase4StageOutput = {
        stage: 'http-server-generation',
        status: 'completed',
        data: {
          framework,
          files: serverFiles,
          routeCount,
        } satisfies HttpServerOutput,
        artifacts: writtenPaths,
        timing,
        summary:
          `Generated ${framework} HTTP server (${language}): ` +
          `${routeCount} routes across ${contexts.length} bounded contexts ` +
          `(${writtenPaths.length} files in ${timing}ms)`,
      };

      context.stageOutputs.set('http-server-generation', output);
      return output;
    }
  } catch (err: unknown) {
    const errorMessage = err instanceof Error ? err.message : String(err);

    const finalRootSpan = endSpan(rootSpan, 'error', { error: errorMessage });
    emitSpan(finalRootSpan);

    const timing = Date.now() - startTime;
    const output: Phase4StageOutput = {
      stage: 'http-server-generation',
      status: 'failed',
      data: { error: errorMessage },
      artifacts: [],
      timing,
      summary: `HTTP server generation failed: ${errorMessage}`,
    };

    context.stageOutputs.set('http-server-generation', output);
    return output;
  }
}
